expedition_advisor.agent_input_schema:
{
  "type": "object",
  "properties": {
    "trainee_exp_remaining": {
      "type": "integer",
      "description": "EXP needed to next level milestone"
    },
    "mewtwo_hp": {
      "type": "integer",
      "description": "Current HP for Mewtwo"
    },
    "mewtwo_status": {
      "type": "string",
      "description": "Status condition for Mewtwo (e.g. OK, PAR, SLP)"
    },
    "mewtwo_psychic_pp": {
      "type": "integer",
      "description": "Remaining PP for Mewtwo's Psychic"
    },
    "blastoise_hp": {
      "type": "integer",
      "description": "Current HP for Blastoise"
    },
    "blastoise_status": {
      "type": "string",
      "description": "Status condition for Blastoise (e.g. OK, PAR, SLP)"
    },
    "blastoise_surf_pp": {
      "type": "integer",
      "description": "Remaining PP for Blastoise's Surf"
    }
  },
  "required": [
    "trainee_exp_remaining",
    "mewtwo_hp",
    "mewtwo_status",
    "mewtwo_psychic_pp",
    "blastoise_hp",
    "blastoise_status",
    "blastoise_surf_pp"
  ]
}

expedition_advisor.agent_output_schema:
{
  "type": "object",
  "properties": {
    "recommendation": {
      "type": "string",
      "enum": ["continue", "pit-stop"],
      "description": "Whether to continue training or return to town for a pit-stop"
    },
    "reasoning": {
      "type": "string",
      "description": "Justification based on party attrition, PP, and trainee requirements"
    },
    "estimated_battles_remaining": {
      "type": "integer",
      "description": "Estimated battles needed to hit the trainee milestone (trainee_exp_remaining / 330)"
    }
  },
  "required": [
    "recommendation",
    "reasoning",
    "estimated_battles_remaining"
  ]
}
